// Desktop 2.0 snapshot: src/main/resolver/ytdlpStream.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// Получение прямого потока через yt-dlp. Общая часть для SoundCloud и YouTube Music.
// Сначала спрашиваем «тёплый» yt-dlp (ytdlpWorker.ts, без запуска программы), если он недоступен,
// запускаем yt-dlp.exe как раньше. Ответ и ошибки в обоих случаях разбираются одинаково.
import { lastErrorLine, runYtdlp, ytdlpBaseArgs, type ToolPaths } from './tools.js';
import type { StreamResult } from './types.js';

/** Подробности ответа yt-dlp -j, которые нам нужны. */
interface YtdlpInfo {
  url?: string;
  protocol?: string;
  ext?: string;
  acodec?: string;
  format_id?: string;
  duration?: number;
  http_headers?: Record<string, string>;
  /** LUFS из ответа плеера YouTube (только тёплый yt-dlp, worker.py). */
  loudness?: number | null;
}

/** Текст ошибки yt-dlp -> понятная причина. */
function failure(msg: string): StreamResult {
  if (/DRM/i.test(msg)) return { ok: false, reason: 'drm', message: msg };
  if (/unavailable|not available|private|removed|404|sign in|age/i.test(msg)) {
    return { ok: false, reason: 'unavailable', message: msg };
  }
  return { ok: false, reason: 'error', message: msg };
}

/** Ответ yt-dlp (из программы или тёплого процесса) -> поток. */
function fromInfo(info: YtdlpInfo): StreamResult {
  if (!info.url) return { ok: false, reason: 'unavailable', message: 'yt-dlp не дал ссылку на звук' };
  // SoundCloud для треков Go+ без подписки отдаёт только 30-секундный кусок
  if (/preview/i.test(info.format_id ?? '')) {
    return { ok: false, reason: 'preview', message: 'доступен только 30-секундный фрагмент' };
  }
  // У ссылок YouTube есть параметр expire (время жизни в секундах от 1970)
  const exp = /[?&]expire=(\d+)/.exec(info.url);
  return {
    ok: true,
    stream: {
      url: info.url,
      protocol: (info.protocol ?? '').includes('m3u8') ? 'hls' : 'http',
      headers: info.http_headers ?? {},
      ext: info.ext ?? '',
      codec: info.acodec ?? '',
      duration: typeof info.duration === 'number' ? info.duration : null,
      expiresAt: exp ? Number(exp[1]) * 1000 : null,
      loudness: typeof info.loudness === 'number' ? info.loudness : null,
    },
  };
}

/** Настройки yt-dlp: обычные или быстрые для YouTube (FAST_ARGS в ytmusic.ts, профиль ytfast в тёплом процессе). */
export type StreamProfile = 'default' | 'ytfast';

/**
 * Спрашивает у yt-dlp лучший аудиопоток (-f bestaudio) для страницы трека.
 * Ничего не скачивает, только получает ссылку. Защищённые (DRM) треки не обходим,
 * а возвращаем причину "drm".
 */
export async function ytdlpGetStream(tools: ToolPaths, pageUrl: string, extraArgs: string[] = [], profile: StreamProfile = 'default', signal?: AbortSignal): Promise<StreamResult> {
  if (tools.worker?.usable) {
    const r = await tools.worker.request({ op: 'stream', url: pageUrl, profile }, 6000, signal);
    if (r?.ok) return fromInfo(r.info as YtdlpInfo);
    // Ответ источника об ошибке ("ERROR: [youtube] ...": песня недоступна и т.п.) окончательный;
    // любой другой сбой (сам процесс, его модули): пробуем программой yt-dlp.exe
    if (r && /^ERROR: \[/m.test(r.error)) return failure(lastErrorLine(r.error));
  }
  const r = await runYtdlp(tools, [...ytdlpBaseArgs(tools), ...extraArgs, '-f', 'bestaudio', '-j', pageUrl], 6000, signal);
  if (r.timedOut) return { ok: false, reason: 'error', message: 'yt-dlp не ответил за 6 секунд' };
  if (r.code !== 0) return failure(lastErrorLine(r.stderr) || `yt-dlp завершился с кодом ${r.code}`);
  let info: YtdlpInfo;
  try {
    info = JSON.parse(r.stdout) as YtdlpInfo;
  } catch {
    return { ok: false, reason: 'error', message: 'yt-dlp вернул не JSON' };
  }
  return fromInfo(info);
}
